Author `app/src/main/ts/prefetch.ts` (~15 lines): document_start IntersectionObserver override:
```ts
(() => {
  const Orig = window.IntersectionObserver;
  if (!Orig) return;
  window.IntersectionObserver = class extends Orig {
    constructor(cb: IntersectionObserverCallback, options?: IntersectionObserverInit) {
      const o = options ?? {};
      if (!o.rootMargin || o.rootMargin === "0px" || o.rootMargin === "") {
        o.rootMargin = "300% 0px 300% 0px";
      }
      super(cb, o);
    }
  };
})();
```
